import{_ as a,o as i,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Механизм открытости и обмена технологиями","description":"","frontmatter":{},"headers":[],"relativePath":"ru/69-技术开放与共享机制.md","filePath":"ru/69-技术开放与共享机制.md","lastUpdated":null}'),d={name:"ru/69-技术开放与共享机制.md"};function e(o,t,h,n,s,u){return i(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="механизм-открытости-и-обмена-технологиями" tabindex="-1">Механизм открытости и обмена технологиями <a class="header-anchor" href="#механизм-открытости-и-обмена-технологиями" aria-label="Permalink to &quot;Механизм открытости и обмена технологиями&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>69</td></tr><tr><td>Модуль</td><td>Технология и энергетические системы</td></tr><tr><td>Ключевые слова</td><td>Открытость технологий, обмен знаниями, открытые законы, популяризация технологий, антимонопольный</td></tr></tbody></table><h2 id="i-ключевая-концепция-открытости-технологии" tabindex="-1">I. Ключевая концепция открытости технологий <a class="header-anchor" href="#i-ключевая-концепция-открытости-технологии" aria-label="Permalink to &quot;I. Ключевая концепция открытости технологий&quot;">​</a></h2><p>Механизм открытости и обмена технологиями Симбиотической Цивилизации Якоря — конкретное воплощение основной программы «больше труда, больше награды; самопроизрастание и саморазвитие; дорога для каждого; совместное продвижение Десяти Тысяч Рас» в технологической сфере. Его ключевая концепция: технологическое знание как продукт коллективной эволюции всей цивилизации должно быть доступно всей цивилизации; технологическая монополия и барьеры знаний — пережитки хищнической системы в технологической сфере, которые должны быть устранены институциональным проектированием.</p><p>Открытость технологий не означает отрицания вклада разработчиков технологий. Напротив, симбиотическая цивилизация создала механизм технологического стимулирования с «измеримыми вкладами и прослеживаемыми выгодами», гарантирующий, что труд разработчиков получает разумное вознаграждение, а технологические достижения приносят пользу всем формам жизни при самом низком пороге. Суть этого механизма — превращение технологии из «товара, монополизированного немногими» в «инфраструктуру, общую для всей цивилизации».</p><h2 id="ii-система-открытости-технологии-по-уровням" tabindex="-1">II. Система открытости технологий по уровням <a class="header-anchor" href="#ii-система-открытости-технологии-по-уровням" aria-label="Permalink to &quot;II. Система открытости технологий по уровням&quot;">​</a></h2><p>Открытость технологий реализуется по уровням в зависимости от уровня риска и зрелости:</p><table tabindex="0"><thead><tr><th>Уровень открытости</th><th>Применимые технологии</th><th>Способ открытости</th><th>Условия доступа</th></tr></thead><tbody><tr><td>Полностью открыто</td><td>Зрелые технологии уровней R0 и R1</td><td>Все технические документы и конструкторские чертежи публично бесплатны</td><td>Без порога; все формы жизни могут получить доступ</td></tr><tr><td>Открыто по лицензии</td><td>Зрелые технологии уровня R2</td><td>Базовые принципы публичны; инженерная реализация требует запроса лицензии</td><td>Необходимо пройти базовую подготовку по безопасности и обязаться соблюдать нормы использования</td></tr><tr><td>Ограниченно открыто</td><td>Технологии уровня R3</td><td>Открыто только уполномоченным исследовательским учреждениям, с подписанием соглашений о безопасности</td><td>Необходимо наличие изолированного пространства уровня S и квалификации этической экспертизы</td></tr><tr><td>Запрещено открывать</td><td>Запретные технологии уровня R4</td><td>Не открываются</td><td>Полный запрет</td></tr></tbody></table><p>Для полностью открытых технологий симбиотическая цивилизация создала «Библиотеку открытых законов» — базу технологических знаний, аналогичную сообществам открытого программного обеспечения реального мира. Все разработчики могут передавать свои технологические достижения в Библиотеку открытых законов, которая после проверки Техническим комитетом открывает их всей цивилизации. Технологии Библиотеки открытых законов используют «Лицензию Симбиотического Обмена», допускающую свободное использование, изменение и перераспределение, но производные произведения должны распространяться открытым образом.</p><h2 id="iii-инфраструктура-популяризации-технологии" tabindex="-1">III. Инфраструктура популяризации технологий <a class="header-anchor" href="#iii-инфраструктура-популяризации-технологии" aria-label="Permalink to &quot;III. Инфраструктура популяризации технологий&quot;">​</a></h2><p>Для обеспечения того, чтобы открытость технологий не оставалась формальностью, симбиотическая цивилизация создала полноценную инфраструктуру популяризации технологий:</p><ol><li><strong>Система технологического образования</strong>: Симбиотическая образовательная система включает базовые знания инженерии законов в общее образование, гарантируя, что каждая форма жизни обладает способностью понимать и применять базовые технологии. Продвинутое технологическое образование открыто бесплатно для всех желающих обучаться.</li><li><strong>Сеть распространения технологий</strong>: на основе сети межплоскостной связи создана общевселенская платформа распространения технологий, включая онлайн-курсы, технологические форумы и виртуальные лаборатории, позволяющая обучающимся в отдалённых плоскостях получать новейшие технологические знания.</li><li><strong>Общественные технологические объекты</strong>: общинные Якоря оснащены общественными технологическими лабораториями и производственным оборудованием, которые любая форма жизни может бронировать, превращая технологические знания в реальные продукты.</li><li><strong>Система технологических наставников</strong>: старшие технические специалисты обязаны периодически выступать технологическими наставниками, руководя начинающими обучающимися; эта обязанность засчитывается в их степень симбиотического вклада.</li></ol><h2 id="iv-измерение-и-стимулирование-технологического-вклада" tabindex="-1">IV. Измерение и стимулирование технологического вклада <a class="header-anchor" href="#iv-измерение-и-стимулирование-технологического-вклада" aria-label="Permalink to &quot;IV. Измерение и стимулирование технологического вклада&quot;">​</a></h2><p>Устойчивость механизма открытости технологий зависит от разумной системы измерения и стимулирования вклада:</p><ul><li><strong>Измерение вклада</strong>: после включения технологических достижений, переданных разработчиками, в Библиотеку открытых законов, на основе их технологической ценности, сферы применения и производного вклада рассчитывается «степень технологического вклада». Степень вклада — важная основа распределения ресурсов в Механизме Совместного Подряда.</li><li><strong>Приоритетное право использования</strong>: разработчики технологий в течение определённого срока пользуются приоритетным правом использования своих достижений и приоритетом в продвинутых услугах, но не имеют права монополизировать право передачи технологий.</li><li><strong>Система почёта</strong>: разработчикам технологий с крупными вкладами в цивилизацию присваиваются почётные знаки, такие как «Медаль Симбиотических Технологий», а их достижения вносятся в технологическую историю цивилизации.</li><li><strong>Непрерывные выгоды</strong>: для продвинутых технологических приложений, требующих больших затрат энергии, разработчики могут получать разумную долю доходов от применения, но доля ограничена верхними пределами антимонопольного закона.</li></ul><h2 id="v-антимонопольное-регулирование-и-технологическая-справедливость" tabindex="-1">V. Антимонопольное регулирование и технологическая справедливость <a class="header-anchor" href="#v-антимонопольное-регулирование-и-технологическая-справедливость" aria-label="Permalink to &quot;V. Антимонопольное регулирование и технологическая справедливость&quot;">​</a></h2><p>Исполнение механизма открытости технологий строго гарантируется антимонопольным законом:</p><ul><li>Запрещается любой организации или индивиду монополизировать права передачи базовых технологий через патентные барьеры, технологическую секретность и иные средства.</li><li>Запрещается «технологическая блокировка», то есть принуждение пользователей к зависимости от конкретных поставщиков технологий путём намеренного создания несовместимых стандартов.</li><li>Вводится принудительная открытость ключевых инфраструктурных технологий (таких как аппаратное обеспечение Якоря, распределение энергии, межплоскостная связь), а их основные стандарты должны совместно разрабатываться всей цивилизацией.</li><li>Создаётся механизм оценки технологической справедливости, периодически оценивающий равномерность популяризации технологий и предоставляющий адресную поддержку отстающим в технологиях плоскостям и группам.</li></ul><h2 id="vi-баланс-между-открытостью-и-безопасностью-технологии" tabindex="-1">VI. Баланс между открытостью и безопасностью технологий <a class="header-anchor" href="#vi-баланс-между-открытостью-и-безопасностью-технологии" aria-label="Permalink to &quot;VI. Баланс между открытостью и безопасностью технологий&quot;">​</a></h2><p>Между открытостью технологий и технологической безопасностью необходимо соблюдать тонкий баланс. Подход симбиотической цивилизации таков:</p><ul><li>Базовые принципы и общие знания полностью открыты, позволяя большему числу людей понимать сущность технологий и тем самым лучше выявлять технологические риски.</li><li>Конкретные параметры и детали реализации высокоопасных операций открыты ограниченно, предоставляются только учреждениям, отвечающим условиям безопасности.</li><li>Знания о запретных технологиях строго засекречены, но этический анализ «почему они запретны» открыт и прозрачен, позволяя всей цивилизации понимать смысл существования границ.</li><li>Установлен кодекс «ответственного распространения технологий», согласно которому распространители технологий обязаны одновременно распространять безопасные методы использования и этические границы.</li></ul><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Механизм открытости и обмена технологиями — одна из ключевых особенностей, отличающих Симбиотическую Цивилизацию Якоря от хищнических цивилизаций. В хищнической системе технология — орудие сильных для подавления слабых; в симбиотической цивилизации технология — лестница совместной эволюции Десяти Тысяч Рас. Благодаря поэтапной открытости, инфраструктуре популяризации, разумному стимулированию и антимонопольным гарантиям симбиотическая цивилизация строит технологическую экосистему «свободного потока знаний, всеобщего повышения способностей и справедливого вознаграждения вкладов», обеспечивающую постоянный источник инновационной динамики для повышения измерения всей цивилизации.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>60-技术体系总览 (Обзор технологической системы)</li><li>68-技术伦理与安全边界 (Технологическая этика и границы безопасности)</li><li>47-反垄断法 (Антимонопольный закон)</li></ul>',25)])])}const p=a(d,[["render",e]]);export{c as __pageData,p as default};
